import * as D from './domain.mjs';
import * as S from './simulation.mjs';
import * as R from './research.mjs';
import * as V from './views.mjs';
import * as M from './mission.mjs';
const KEY='CHNAI_CREW_HEALTH_MOCK_V1';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),notifications=document.querySelector('#notifications');
let state,role='crew',subjectId='SIM-C03',reviewerId='SIM-A02',view='today',guide=false,lastSaved=null,storageProblem='',modalReturn=null;
let selectedScenario='nominal',checkResults=[],researchReport=null,researchError='',researchLoading=false,researchSubject='C001',researchAnalyte='WHITE BLOOD CELL COUNT';
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={review:'M3 12h4l3-7 4 14 3-7h4',care:'M9 4h6v3H9z M7 5H5v16h14V5h-2 M8 12h8 M8 16h5',transfer:'M4 8h15 M15 4l4 4-4 4 M20 17H5 M9 13l-4 4 4 4',evidence:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',system:'M4 5h16v12H4z M8 21h8 M12 17v4',arrow:'M5 12h14 M14 7l5 5-5 5',link:'M10 13l4-4 M8 15l-2 2a3 3 0 0 1-4-4l4-4a3 3 0 0 1 4 0 M14 9l2-2a3 3 0 0 1 4 4l-4 4a3 3 0 0 1-4 0',external:'M14 4h6v6 M20 4l-9 9 M10 5H4v15h15v-6',info:'M12 8h.01 M12 11v6 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M6 18L18 6',plus:'M12 5v14 M5 12h14',clock:'M12 7v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',shield:'M12 3l8 3v6c0 5-8 9-8 9S4 17 4 12V6z M8 12l3 3 5-6',play:'M8 5l11 7-11 7z',edit:'M14 5l5 5 M4 20l4-1L20 7a3 3 0 0 0-4-4L4 15z',refresh:'M20 5v5h-5 M4 19v-5h5 M6 7a8 8 0 0 1 14 3 M18 17a8 8 0 0 1-14-3'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[n]??icons.info}"/></svg>`;
const btn=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${e(label)}${icon('arrow')}</button>`;
const textBtn=(label,action,extra='')=>`<button class="text-btn" data-action="${action}" ${extra}>${e(label)}${icon('arrow')}</button>`;
const badge=(label,cls='')=>`<span class="badge ${cls}">${e(label)}</span>`;
const actor=()=>D.actorFor(role,subjectId,reviewerId);
const sid=()=>role==='onboard'?'SIM-C03':subjectId;
const fmtTime=t=>{if(!t)return '—';return new Date(t).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});};
const fmtEvent=t=>!t?'—':state.simulation?'+'+S.clockLabel(Math.max(0,(Date.parse(t)-Date.UTC(2026,0,1))/1000)):fmtTime(t);
const subject=()=>D.SUBJECTS.find(s=>s.id===sid());
function readStored(){const raw=localStorage.getItem(KEY);if(!raw)return null;const s=D.migrateState(JSON.parse(raw));if(s.schema!==D.SCHEMA||!Array.isArray(s.records)||!Array.isArray(s.packets)||!s.faults||!Number.isInteger(s.version))throw new Error('Stored mock data has an unsupported format.');return s;}
try{state=readStored()??D.createState();if(state.simulation){state.simulation.running=false;selectedScenario=state.simulation.id;}localStorage.setItem(KEY,JSON.stringify(state));lastSaved=new Date().toISOString();}catch(err){state=D.createState();storageProblem='Browser storage is unavailable or the stored mock needs a reset. Changes cannot be confirmed as saved.';}
try{const ui=JSON.parse(sessionStorage.getItem(KEY+'_VIEW')??'null');if(ui&&D.LABELS[ui.role]){role=ui.role;subjectId=D.SUBJECTS.some(x=>x.id===ui.subjectId)?ui.subjectId:'SIM-C03';reviewerId=D.reviewerFor(state,ui.reviewerId)?ui.reviewerId:'SIM-A02';view=ui.view;}}catch{}
function transact(fn,{control=false}={}){
 try{
  if(!control)D.requireLocal(state);
  const stored=readStored();if(stored&&stored.version!==state.version){state=stored;closeModal();render();throw new Error('The simulation changed in another tab. Review the updated state and try again.');}
  const next=D.clone(state),result=fn(next);next.version=state.version+1;
  localStorage.setItem(KEY,JSON.stringify(next));state=next;lastSaved=new Date().toISOString();storageProblem='';return {ok:true,result};
 }catch(err){if(err.name==='QuotaExceededError'||err.name==='SecurityError')storageProblem='This change could not be saved to browser storage.';notify(err.message,true);render();return {ok:false,error:err};}
}
function notify(message,error=false){notifications.innerHTML=`<div class="toast ${error?'error':''}">${e(message)}</div>`;clearTimeout(notify.timer);notify.timer=setTimeout(()=>notifications.innerHTML='',5200);}
function closeModal(){if(modal.open)modal.close();modal.innerHTML='';if(modalReturn?.isConnected)modalReturn.focus();}
function showModal(title,body){modalReturn=document.activeElement;modal.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!modal.open)modal.showModal();modal.querySelector('button')?.focus();}
function heading(kicker,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${e(kicker)}</div><h1>${e(title)}</h1><p>${e(subtitle)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function empty(title,description,action='',ico='evidence'){return `<section class="panel empty"><div class="empty-mark">${icon(ico)}</div><h2>${e(title)}</h2><p>${e(description)}</p>${action}</section>`;}
function metaRows(rows){return `<dl class="meta-list">${rows.map(([k,v])=>`<div class="meta-row"><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl>`;}
function readAllowed(){return D.canRead(state,actor(),sid());}
function guideBox(){
 if(!guide)return '';
 const c=D.comparison(state,'SIM-C03'),ep=D.episodeFor(state,'SIM-C03'),review=D.currentReview(state,'SIM-C03'),p=state.packets.findLast(p=>p.subjectId==='SIM-C03');
 let title,description,label,action,extra='';
 if(!c.current){title='01 / Gather the assessment';description='Import the fictional completed assessment. Its original time and method stay attached.';label='Open intake';action='guide-crew';}
 else if(!ep){title='02 / Evaluate and request review';description='Inspect the 78% comparison and its limitations, then request onboard review.';label='Crew workspace';action='guide-crew';}
 else if(!ep.acceptance){title='03 / Accept review responsibility';description='Open Crew today to inspect duty availability, request a backup if needed, and accept the offered assignment.';label='Open crew today';action='go-today';}
 else if(!review){title='04 / Record an onboard review';description='Switch to the assigned reviewer. Record a context question and a follow-up trigger.';label='Onboard reviewer';action='guide-onboard';}
 else if(!p||p.historical){title='04 / Prepare an exact handoff';description='Preview the recipient, evidence revisions and payload. Approve that exact version.';label='Prepare handoff';action='guide-handoff';}
 else if(!p.receipt){title='05 / Deliver when the link returns';description='The approved packet stays queued in this browser. Reconnect the simulated Earth link to deliver it.';label='Open transfer';action='guide-transfer';}
 else if(!p.groundReview){title='06 / Review the received snapshot';description='Ground reads the immutable packet and records a separate simulated review.';label='Ground reviewer';action='guide-ground';}
 else{title='07 / Responsibility survives delivery';description='Ground review is recorded. The onboard follow-up remains assigned until its owner records an outcome.';label='View follow-up';action='guide-onboard';}
 return `<div class="guide"><div><strong>${e(title)}</strong><p>${e(description)}</p></div>${btn(label,action,'small',extra)}<button class="text-btn" data-action="end-guide" aria-label="End walkthrough">${icon('close')}</button></div>`;
}
function footer(){return `<div class="page-footer"><span>Fictional crew data · Demonstration only · Clinical applicability unreviewed</span><span>${storageProblem?'Save unavailable':`Saved in this browser${lastSaved?' · '+fmtTime(lastSaved):''}`}</span></div>`;}
function render(){
 try{sessionStorage.setItem(KEY+'_VIEW',JSON.stringify({role,subjectId,reviewerId,view}));}catch{}
 const focus=document.activeElement,focusId=focus?.id,focusAction=focus?.dataset?.action,focusKey=focus?.dataset?.key;
 const nav=role==='technical'?[['system','System status','system'],['lab','Scenario lab','play'],['research','Research data','evidence'],['evidence','Source library','evidence']]:role==='ground'?[['ground','Received packets','care'],['lab','Scenario lab','play'],['research','Research data','evidence'],['evidence','Source library','evidence'],['system','System status','system']]:[['today','Crew today','clock'],['brief','Health brief','review'],['review','Assessment detail','review'],['care','Follow-up','care'],['transfer','Ground handoff','transfer'],['research','Research data','evidence'],['lab','Scenario lab','play'],['evidence','Evidence & sources','evidence'],['system','System status','system']];
 if(!nav.some(n=>n[0]===view))view=nav[0][0];
 const ep=['crew','onboard'].includes(role)?D.episodeFor(state,sid()):null;
 const pendingCount=ep?.followUps.filter(f=>f.state==='pending').length??0;
 const body=view==='today'?(sid()==='SIM-C03'?M.todayPage({state,actor:actor(),subjectId:sid()}):V.briefPage({state,role,subjectId,reviewerId})):view==='brief'?V.briefPage({state,role,subjectId,reviewerId}):view==='lab'?V.labPage({state,selectedScenario,checkResults}):view==='research'?V.researchPage({report:researchReport,error:researchError,loading:researchLoading,researchSubject,analyte:researchAnalyte}):view==='review'?reviewPage():view==='care'?carePage():view==='transfer'?transferPage():view==='ground'?groundPage():view==='evidence'?evidencePage():systemPage();
 app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="./mark.svg" alt=""><div><div class="brand-name">CHNAI</div><div class="brand-sub">CREW HEALTH</div></div><span class="mobile-brand">MISSION SIMULATION</span></div><div class="nav-label">ONBOARD WORKSPACE</div><nav class="nav" aria-label="Workspace">${nav.map(([id,label,ico])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}${e(label)}${id==='care'&&pendingCount?'<span class="nav-count">'+pendingCount+'</span>':''}</button>`).join('')}</nav><div class="mission-panel"><div class="side-kicker">MISSION CONTEXT</div><strong>Deep-space transit</strong><p>SIM-TRANSIT-01</p><p>Scenario day 030</p></div><div class="sidebar-bottom"><b>CHNAI LAB</b>Independent design prototype<br>Evidence-led. Crew-centered.<br><br>Crew records are fictional.<br>Research records stay separate.</div></aside><div class="workspace"><header class="topbar"><div class="topbar-title">Crew health workspace <span>/ ${e(role==='ground'?'Ground review':role==='technical'?'Systems':subject()?.id??'SIM-C03')}</span></div><div class="status-row"><span class="status"><i class="dot ${state.faults.node&&state.faults.lan?'':'amber'}"></i>Local ${state.faults.node&&state.faults.lan?'available':'unavailable'}</span><span class="status"><i class="dot ${state.faults.earth?'':'amber'}"></i>Earth ${state.faults.earth?'connected':'disconnected'}</span><div class="context-controls"><label class="sr-only" for="role-select">Simulation role</label><select id="role-select" data-change="role" aria-label="Simulation role">${Object.entries(D.LABELS).map(([k,v])=>`<option value="${k}" ${role===k?'selected':''}>${e(v)}</option>`).join('')}</select>${role==='crew'?`<label class="sr-only" for="subject-select">Fictional crew member</label><select id="subject-select" data-change="subject" aria-label="Fictional crew member">${D.SUBJECTS.map(s=>`<option value="${s.id}" ${s.id===subjectId?'selected':''}>${e(s.label)} · ${e(s.id)}</option>`).join('')}</select>`:role==='onboard'?`<label class="sr-only" for="reviewer-select">Onboard reviewer</label><select id="reviewer-select" data-change="reviewer" aria-label="Onboard reviewer">${state.operations.reviewers.map(r=>`<option value="${e(r.id)}" ${reviewerId===r.id?'selected':''}>${e(r.label)} · ${r.id==='SIM-A02'?'Primary':'Backup'}</option>`).join('')}</select>`:`<span class="badge">${role==='ground'?'SIM-GROUND-01':'Metadata only'}</span>`}</div></div></header><div class="simulation-band"><p><span class="sim-label">MISSION SIMULATION</span><span>Fictional crew and links. Real research files have a separate workspace. Role switching is a simulation.</span></p><button class="text-btn" data-action="go-lab">${icon('play')}${state.simulation?.running?'Replay running':'Scenario lab'}<span data-replay-clock>${state.simulation?' +'+S.clockLabel(state.simulation.elapsed):''}</span></button></div>${storageProblem?`<div class="notice error global-fault">${e(storageProblem)}</div>`:''}${!state.faults.node||!state.faults.lan?`<div class="notice error global-fault">${!state.faults.node?'Simulated local node unavailable.':'Simulated device link unavailable.'} Showing cached demonstration data. New actions cannot be confirmed as saved. ${textBtn('Restore in system status','go-system')}</div>`:''}<main class="main" id="main" tabindex="-1">${guideBox()}${body}${footer()}</main></div></div>`;
 if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});else if(focusAction){const candidates=[...document.querySelectorAll('[data-action]')];candidates.find(x=>x.dataset.action===focusAction&&x.dataset.key===focusKey)?.focus({preventScroll:true});}
}
function reviewPage(){
 if(!readAllowed())return heading('CARE RELATIONSHIP','No assigned access','The selected simulation role cannot read this crew record.')+empty('Care relationship unavailable','Restore the reviewer relationship in simulation controls to continue.',btn('Open system status','go-system'));
 const r=D.comparison(state,sid()),ep=D.episodeFor(state,sid()),review=D.currentReview(state,sid());
 const actions=role==='onboard'?btn('Correct assessment','correct','',r.current&&D.ownsReview(state,actor(),sid())?'':'disabled'):btn('Replay fixture','replay','',!state.faults.node||!state.faults.lan?'disabled':'');
 let card;
 if(!r.current)card=empty('Ready to gather an assessment','The selected preflight baseline is available. Import the fictional completed assessment to begin the review.',btn('Import demonstration assessment','replay','primary'),'review');
 else if(!r.evaluable)card=`<section class="panel"><div class="panel-heading"><h2>${icon('review')}Assessment needs context</h2>${badge('Not evaluable','amber')}</div><div class="panel-pad"><p class="muted">The comparison is unavailable because a required input has not passed the demonstration checks.</p><ul class="checks">${r.checks.map(([k,ok])=>`<li><span>${e(k)}</span><span class="${ok?'ok':'bad'}">${ok?'Available':'Missing / incompatible'}</span></li>`).join('')}</ul>${textBtn('Inspect original evidence','evidence-detail')}</div></section>`;
 else{
 const pct=Math.min(Number(r.percent),100);const diff=Math.abs(80-Number(r.percent)).toFixed(2).replace(/\.00$/,'');
 card=`<section class="panel"><div class="comparison-header"><div><h2>Aerobic capacity assessment</h2><p>Completed assessment · ${e(r.current.method)}</p></div>${badge('Demo comparison',r.below?'amber':'blue')}</div><div class="metrics"><div class="metric"><div class="metric-label">Current assessment</div><div class="metric-value ${r.current.value.length>4?'precision':''}">${e(r.current.value)}</div><div class="metric-unit">mL/min/kg</div><div class="metric-sub">Scenario time · ${e(r.current.time)}</div></div><div class="metric"><div class="metric-label">Selected preflight baseline</div><div class="metric-value">${e(r.baseline.value)}</div><div class="metric-unit">mL/min/kg</div><div class="metric-sub">Scenario time · ${e(r.baseline.time)}</div></div><div class="metric"><div class="metric-label">Capacity retained</div><div class="metric-value ${r.below?'amber':''} ${r.percent.length>4?'precision':''}">${e(r.percent)}<span style="font-size:23px">%</span></div><div class="metric-unit">of selected baseline</div><div class="metric-sub">${diff==='0'?'At the 80% reference':`${e(diff)} percentage points ${r.below?'below':'above'} reference`}</div></div></div><div class="comparison-plot"><div class="plot-label"><span>Current relative to baseline</span><strong>NASA V1 4003 · reference ≥ 80%</strong></div><div class="capacity-track" role="img" aria-label="${e(r.percent)} percent of baseline. Reference 80 percent."><div class="capacity-fill ${r.below?'below':''}" style="width:${pct}%"></div><div class="capacity-reference" style="left:80%"></div><div class="capacity-baseline"></div></div><div class="plot-axis"><span>0%</span><span>80% reference</span><span>100% baseline</span></div></div><div class="comparison-notice">${icon('info')}<span>Demonstration arithmetic. Method comparability is assumed for this fixture. Measurement uncertainty is unspecified; clinical applicability has not been reviewed.</span></div></section>`;
 }
 let action,actionDetail,owner;
 if(role==='crew'){owner=ep?'Onboard ownership · '+(ep.owner??'Acceptance pending'):'Crew member · '+sid();actionDetail=ep?'Your request is saved. The assigned reviewer can inspect the same evidence.':'Request a review of the assessment context and what the comparison means.';action=ep?btn('View review episode','go-care','primary'):btn('Request onboard review','request-review','primary',sid()!=='SIM-C03'||!r.current?'disabled':'');if(sid()!=='SIM-C03')actionDetail='The complete review workflow is configured for Crew 03. Other crew fixtures demonstrate data and boundary conditions.';}
 else{owner='Onboard reviewer · '+reviewerId;actionDetail=review?'Current evidence has a recorded context review. Follow-up remains accountable.':ep?'Record the context question, responsible actor and next follow-up trigger.':'A crew review request is needed before recording a disposition.';action=D.ownsReview(state,actor(),sid())?(review?btn('View follow-up','go-care','primary'):btn('Record onboard review','record-review','primary')):btn('Review assignment','go-today','primary');}
 const explanation=r.evaluable?`The current assessment is <strong>${e(r.current.value)} mL/min/kg</strong>, compared with a selected baseline of <strong>${e(r.baseline.value)} mL/min/kg</strong>. This is <strong>${e(r.percent)}% of baseline</strong>, ${r.below?'below':'at or above'} the 80% relative reference.<br><br>This comparison does not establish a diagnosis or fitness-for-duty decision. The next step is to review the assessment method, baseline and uncertainty.`:'The available measurement is preserved. A reference comparison is withheld until the listed input gaps are resolved. A review request can still ask for the missing context.';
 return heading('INDIVIDUAL HEALTH REVIEW',role==='crew'?'Your health review':'Assigned health review',`${subject()?.label} · ${subject()?.role} · Deep-space transit`,actions)+`<div class="grid-main"><div class="stack">${card}<section class="panel"><div class="panel-heading"><h2>Other health domains</h2><span class="muted">Outside this demo assessment</span></div><div class="domain-list">${['Immune function','Bone health','Behavioral health','Radiation exposure'].map(n=>`<div class="domain-item"><div class="domain-name">${n}</div><div class="domain-value">Not assessed</div></div>`).join('')}</div></section>${activityPanel(sid(),4)}</div><div class="stack"><section class="panel"><div class="insight"><div class="mini-head">${icon('info')}Explanation · template</div><h2>${r.evaluable?(r.below?'A change worth reviewing':'Understand this assessment'):'Resolve the missing context'}</h2><p>${explanation}</p><div class="source-line">${icon('evidence')}<a href="${SOURCE_URL()}" target="_blank" rel="noopener noreferrer">NASA-STD-3001 · V1 4003 ${icon('external')}</a></div></div><div class="responsibility"><div class="responsibility-label">NEXT RESPONSIBLE ACTOR</div><strong>${e(owner)}</strong><p>${e(actionDetail)}</p>${action}</div></section><section class="panel panel-pad"><div class="mini-head">${icon('shield')}Evidence context</div>${metaRows([['Data origin','Fictional assessment'],['Input checks',r.evaluable?'Demo checks complete':'Context missing'],['Clinical approval','Not reviewed'],['Uncertainty','Not specified'],['Evidence revision',r.current?'r'+r.current.revision:'Not imported']])}${r.current?textBtn('Inspect evidence','evidence-detail'):''}</section></div></div>`;
}
function SOURCE_URL(){return D.SOURCE.url;}
function activityPanel(subjectId,limit=5){
 const items=state.events.filter(x=>x.subjectId===subjectId).slice(-limit).reverse();
 return `<section class="panel"><div class="panel-heading"><h2>Episode activity</h2><span class="muted">${state.simulation?'Synthetic event clock':'Browser events'}, not measurement times</span></div><div class="panel-pad">${items.length?`<ol class="activity">${items.map(x=>`<li><span class="activity-time">${e(fmtEvent(x.time))}</span><div><strong>${e(x.detail)}</strong><p>${e(x.actor)} · ${e(x.id)}</p></div></li>`).join('')}</ol>`:'<p class="muted" style="font-size:11px;margin:0">Fictional scenario loaded. No review actions recorded yet.</p>'}</div></section>`;
}
function carePage(){
 if(!readAllowed())return empty('Care relationship unavailable','The current simulation role has no assigned access.',btn('Open system status','go-system'));
 const ep=D.episodeFor(state,sid()),review=D.currentReview(state,sid());
 if(!ep)return heading('ACCOUNTABLE NEXT STEPS','Care workflow','A review request creates an episode with an assigned actor.')+empty('No review request yet','Return to the assessment and request an onboard review of its context.',btn('Open health review','go-review','primary'),'care');
 const pending=ep.followUps.filter(f=>f.state==='pending');
 const step=[['Request',true],['Onboard review',!!review],['Follow-up',!!review&&!pending.length],['Ground review',state.packets.some(p=>p.subjectId===sid()&&p.groundReview)]];
 return heading('ACCOUNTABLE NEXT STEPS',`Review episode ${ep.id}`,`${subject()?.label} · ${review?'Context review recorded':'Awaiting review of current evidence'}`,D.ownsReview(state,actor(),sid())&&!review?btn('Record onboard review','record-review','primary'):'')+`<div class="workflow-banner"><div class="steps">${step.map(([name,done],i)=>`<span class="${done?'done':i===1&&!review?'current':''}"><i>${done?'✓':i+1}</i>${name}</span>`).join('')}</div>${textBtn('Open assessment','go-review')}</div>${ep.state==='needs_review'?'<div class="notice">The assessment has a newer revision. Earlier reviews remain in history; the current evidence needs a new review.</div>':''}<div class="grid-main"><div class="stack"><section class="panel"><div class="panel-heading"><h2>Onboard review</h2>${badge(review?'Recorded':'Awaiting review',review?'blue':'amber')}</div>${ep.reviews.length?ep.reviews.slice().reverse().map(r=>`<div class="review-block"><h3>${e(r.disposition)}</h3><p>${e(r.note)}</p><div class="meta">${e(r.actor)} · ${state.simulation?'Scenario event':'Browser event'} ${e(fmtEvent(r.time))} · ${r.dependency===D.dependency(state,sid())?'Current evidence':'Historical evidence revision'}</div></div>`).join(''):`<div class="panel-pad"><p class="muted" style="font-size:12px">The assigned onboard reviewer will inspect the evidence and record a disposition. No medical outcome is assumed.</p>${role==='crew'?btn('Switch to onboard reviewer','switch-onboard','small'):btn('Review assignment','go-today','primary')}</div>`}</section><section class="panel"><div class="panel-heading"><h2>Follow-up responsibility</h2>${badge(pending.length?pending.length+' pending':'No pending task',pending.length?'amber':'')}</div>${ep.followUps.length?ep.followUps.map(f=>`<div class="review-block"><div style="display:flex;justify-content:space-between;gap:12px"><h3>Verify assessment context</h3>${badge(f.state==='pending'?'Pending':'Outcome recorded',f.state==='pending'?'amber':'green')}</div>${metaRows([['Owner',f.owner],['Due event',f.trigger]])}${f.outcome?`<p style="margin-top:12px">${e(f.outcome)}</p>`:''}${D.ownsReview(state,actor(),sid())&&f.state==='pending'&&f.owner===actor().id?`<div class="card-actions">${btn('Record follow-up outcome','follow-up','small',`data-id="${e(f.id)}"`)}</div>`:''}</div>`).join(''):'<div class="panel-pad"><p class="muted" style="font-size:12px;margin:0">A follow-up owner and trigger are recorded with the review disposition.</p></div>'}</section>${activityPanel(sid(),6)}</div><div class="stack">${M.responsibilityPanel({state,actor:actor(),subjectId:sid()})}<section class="panel panel-pad"><div class="mini-head">${icon('care')}Current responsibility</div>${metaRows([['Crew member',sid()],['Accepted owner',ep.owner??'Awaiting acceptance'],['Current evidence reviewed',review?'Yes, demonstration only':'No'],['Pending follow-up',String(pending.length)],['Clinical interpretation','Unreviewed']])}</section><section class="panel"><div class="insight"><h2>Keep ground informed</h2><p>A purpose-limited handoff carries the exact evidence and review context. Delivery and ground review remain separate from this follow-up.</p>${role==='onboard'?btn('Prepare ground handoff','prepare-handoff','primary',review&&D.ownsReview(state,actor(),sid())?'':'disabled'):btn('View ground handoff','go-transfer')}</div></section></div></div>`;
}
function transferPage(){
 if(!readAllowed())return empty('Care relationship unavailable','This role cannot inspect the selected crew packets.',btn('Open system status','go-system'));
 const packets=state.packets.filter(p=>p.subjectId===sid()).slice().reverse();const draft=state.drafts.findLast(d=>d.subjectId===sid()&&!d.released&&!d.stale);
 return heading('PURPOSE-LIMITED TRANSFER','Ground handoff','Approved versions keep their original evidence. Receipt is separate from medical review.',role==='onboard'?btn('Prepare handoff','prepare-handoff','primary',D.currentReview(state,sid())&&D.ownsReview(state,actor(),sid())?'':'disabled'):'')+`<div class="notice ${state.faults.earth?'neutral':''}">${icon('link')} Simulated Earth link ${state.faults.earth?'connected':'disconnected'}. ${state.faults.earth?(state.simulation?'Run replay in the scenario lab to model delivery and acknowledgement.':'Delivery can be simulated for queued packets.'):'Approved packets remain queued in this browser.'} No data is sent to an external medical service.</div>${draft?`<section class="panel queue-card" style="margin-bottom:20px"><div><h3>Preview awaiting approval</h3><p>${e(draft.packetId)} · Recipient SIM-GROUND-01 · Current evidence</p></div>${btn('Inspect preview','open-draft','',`data-id="${e(draft.id)}"`)}</section>`:''}${packets.length?`<section class="panel">${packets.map(packetCard).join('')}</section>`:empty('No released packets','Prepare a handoff after the assigned reviewer has recorded a disposition. A preview alone does not send or release data.',role==='onboard'&&D.currentReview(state,sid())?btn('Prepare handoff','prepare-handoff','primary'):'','transfer')}`;
}
function packetCard(p){return `<article class="packet-card"><div class="packet-head"><div><h3>${e(p.id)} · ${p.receipt?'Received by simulated ground':'Queued in this browser'}</h3><p>SIM-GROUND-01 · Assessment-context review · Approved ${e(fmtEvent(p.approvedAt))}</p></div>${badge(p.historical?'Historical evidence':p.groundReview?'Ground review recorded':p.receipt?'Awaiting ground review':'Queued',p.historical||!p.receipt?'amber':'blue')}</div><div class="packet-states"><span class="reached">Approved</span><span class="${p.receipt?'reached':''}">Receiver acknowledgement</span><span class="${p.groundReview?'reached':''}">Ground review</span></div><div class="hash">SHA-256 · ${e(p.hash)}</div>${p.historical?'<p class="muted" style="font-size:11px">A newer local assessment revision exists. This approved snapshot remains unchanged.</p>':''}<div class="card-actions">${textBtn('Inspect released snapshot','packet-detail',`data-id="${e(p.id)}"`)}${role==='onboard'&&!p.receipt&&!state.simulation?btn('Simulate delivery','deliver','small',`data-id="${e(p.id)}" ${state.faults.earth?'':'disabled'}`):''}${role==='onboard'&&!state.faults.earth&&!p.receipt?textBtn('Connect simulated link','connect-earth'):''}${p.receipt&&!p.groundReview?textBtn('Switch to ground reviewer','switch-ground'):''}</div>${p.groundReview?`<div class="detail-note" style="margin-top:17px">Ground review: ${e(p.groundReview.note)}<br><span class="muted">${e(p.groundReview.actor)} · ${e(fmtEvent(p.groundReview.reviewedAt))}. Onboard follow-up has its own state.</span></div>`:''}</article>`;}
function groundPage(){
 const packets=D.groundPackets(state,actor()).slice().reverse();
 return heading('GROUND REVIEW SIMULATION','Received packet workspace','Only received, released snapshots are visible to this role.')+(packets.length?`<div class="stack">${packets.map(p=>`<section class="panel"><div class="panel-heading"><h2>${e(p.id)} · ${e(p.payload.subjectId)}</h2>${badge(p.groundReview?'Review recorded':'Awaiting review',p.groundReview?'blue':'amber')}</div><div class="panel-pad"><div class="key-value-grid"><div><div class="kv-label">Purpose</div><div class="kv-value">${e(p.payload.purpose)}</div></div><div><div class="kv-label">Snapshot status</div><div class="kv-value">Approved received snapshot · onboard changes are not inferred</div></div><div><div class="kv-label">Current assessment in this packet</div><div class="kv-value">${e(p.payload.assessment.current.value)} ${e(p.payload.assessment.current.unit)} · ${e(p.payload.assessment.current.time)}</div></div><div><div class="kv-label">Retained capacity in this packet</div><div class="kv-value">${e(p.payload.comparison.percentOfBaseline)}% of selected baseline</div></div></div><div class="divider"></div><div class="detail-note">Clinical applicability unreviewed. Uncertainty unspecified. This role reads the frozen packet; it does not read the onboard live record.</div>${p.payload.question?`<p><strong style="font-size:11px">Question from onboard review</strong><br><span class="muted" style="font-size:12px">${e(p.payload.question)}</span></p>`:''}${p.groundReview?`<div class="review-block" style="padding-left:0;padding-right:0"><h3>Ground context review recorded</h3><p>${e(p.groundReview.note)}</p><div class="meta">${e(p.groundReview.actor)} · ${e(fmtEvent(p.groundReview.reviewedAt))} · Exact packet hash retained</div></div>`:''}<div class="card-actions">${btn('Inspect received evidence','packet-detail','',`data-id="${e(p.id)}"`)}${!p.groundReview?btn('Record ground review','ground-review','primary',`data-id="${e(p.id)}"`):''}</div></div></section>`).join('')}</div>`:empty('No packet has been received','A released packet must receive a simulated acknowledgement before it becomes visible to ground. No live onboard medical records are shown.',btn('Switch to onboard reviewer','switch-onboard'),'transfer'));
}
function evidencePage(){
 const publicSources=`<section class="panel"><div class="panel-heading"><h2>Source library</h2><span class="muted">Primary references</span></div>${D.SOURCES.map(s=>`<div class="source-card"><div><strong>${e(s.id)}</strong><p>${e(s.label)}</p></div><a class="text-btn" href="${e(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${e(s.id)}">${icon('external')}</a></div>`).join('')}</section>`;
 if(role==='technical'||role==='ground')return heading('TRACEABLE REFERENCES','Evidence & source library','Sources inform the design. Medical evidence access follows the simulated role.')+publicSources+`<div class="notice neutral" style="margin-top:20px">${role==='technical'?'Technical operators see system metadata and public sources. Individual medical values, notes and exports are hidden from this view.':'Individual medical evidence is available only inside this role’s received packet snapshots.'}</div>`;
 if(!readAllowed())return publicSources;
 const [b,c]=D.activeRecords(state,sid());return heading('TRACEABLE REFERENCES','Evidence & source library','Original quantities, scenario times and immutable revisions stay connected.')+`<div class="stack"><section class="panel"><div class="panel-heading"><h2>Assessment provenance · ${e(sid())}</h2>${c?textBtn('Inspect evidence','evidence-detail'):''}</div><div class="table-wrap"><table><thead><tr><th>Record</th><th>Value and raw unit</th><th>Original time</th><th>Provenance</th></tr></thead><tbody>${[[b,'Selected baseline'],[c,'Current assessment']].map(([r,l])=>`<tr><td>${l}<div class="table-detail">${e(r?.id??'Missing')}</div></td><td>${e(r?r.value+' '+r.unit:'Unavailable')}</td><td>${e(r?.time??'Unavailable')}<div class="table-detail">UTC unavailable</div></td><td>Fictional fixture<div class="table-detail">Clinical approval: no</div></td></tr>`).join('')}</tbody></table></div></section>${publicSources}</div>`;
}
function systemPage(){
 const counts={imports:state.imports.length,queued:state.packets.filter(p=>!p.receipt).length,received:state.packets.filter(p=>p.receipt).length};
 return heading('SIMULATION CONTROLS','System status','Connection faults are independent. All transfer activity stays inside this browser.')+`<div class="technical-summary"><section class="panel"><div class="kv-label">Import receipts</div><strong>${counts.imports}</strong><div class="table-detail">Fictional fixture intake</div></section><section class="panel"><div class="kv-label">Queued packets</div><strong>${counts.queued}</strong><div class="table-detail">Awaiting simulated receipt</div></section><section class="panel"><div class="kv-label">Received packets</div><strong>${counts.received}</strong><div class="table-detail">Receipt is separate from review</div></section></div><div class="two-col"><div class="stack"><section class="panel"><div class="panel-heading"><h2>Connection simulation</h2>${badge('Controls for this mock')}</div><div class="panel-pad">${[['earth','Earth communication link','Disconnecting this link keeps local review available.'],['lan','Device-to-node link','Simulated loss prevents new authoritative saves.'],['node','Local onboard node','Simulated loss displays cached data and blocks workflow writes.'],['grant','Onboard reviewer relationship','Revocation blocks the reviewer’s access and packet release.']].map(([k,l,p])=>`<div class="toggle-row"><div><strong>${l}</strong><p>${p}</p></div><button class="toggle ${state.faults[k]?'on':'off'}" data-action="toggle-fault" data-key="${k}" aria-label="${l}: ${state.faults[k]?'available':'unavailable'}" aria-pressed="${state.faults[k]}">${state.faults[k]?'Available':'Unavailable'}</button></div>`).join('')}</div></section><section class="panel panel-pad"><div class="mini-head">${icon('info')}Explanation status</div>${metaRows([['Mode','Deterministic template'],['Local LLM','Not connected'],['External AI calls','None'],['Medical actions from AI','None']])}<p class="muted" style="font-size:11px">The explanation uses the exact recorded facts. A qualified local model remains a later integration.</p></section></div><div class="stack"><section class="panel panel-pad"><div class="mini-head">${icon('system')}Prototype boundaries</div>${metaRows([['Crew data','Fictional'],['Research','Separate OSD-569 source files'],['Live devices','Not connected'],['NASA flight API','Not connected'],['Storage','This browser only'],['Role selector','Simulation, not authentication'],['Backend database','Not implemented']])}<div class="divider"></div><p class="muted" style="font-size:11px;line-height:1.8">The research package specifies the future database, API and device adapters. This interactive mock demonstrates the review workflow; browser storage can be cleared by the browser.</p>${textBtn('Read prototype notes','about')}</section><section class="panel panel-pad"><div class="mini-head">${icon('refresh')}Demonstration tools</div><p class="muted" style="font-size:11px;line-height:1.8">Start a fresh intake-to-handoff walkthrough, or restore the original fictional fixtures. Reset affects this mock’s data in this browser.</p><div class="card-actions">${btn('Start walkthrough','start-guide','small')}${btn('Reset mock data','reset','small')}</div></section></div></div>${role==='technical'?M.staffingControls(state):''}`;
}

function showEvidence(){
 if(!readAllowed())return notify('This role cannot inspect individual onboard records.',true);
 const r=D.comparison(state,sid()),all=state.records.filter(x=>x.subjectId===sid()&&x.kind==='current').sort((a,b)=>b.revision-a.revision);
 showModal('Assessment evidence',`<div class="notice neutral">Fictional engineering fixture. Structural demo checks do not establish clinical validity.</div>${metaRows([['Subject / namespace',sid()+' / SIM-CHNAI-01'],['Mission','SIM-TRANSIT-01 · transit'],['Assessment method',r.current?.method??'Not imported'],['Measurement time',r.current?.time??'Unavailable'],['Baseline time',r.baseline?.time??'Unavailable'],['UTC mapping','Unavailable; not inferred'],['Uncertainty','Not specified'],['Clinical approval','Not reviewed']])}<h3>Input checks</h3><ul class="checks">${r.checks.map(([l,ok])=>`<li><span>${e(l)}</span><span class="${ok?'ok':'bad'}">${ok?'Complete for demo':'Missing / incompatible'}</span></li>`).join('')}</ul><h3>Current-assessment revisions</h3>${all.map(x=>`<div class="review-block" style="padding:13px 0"><h3>${e(x.id)} · ${e(x.value)} ${e(x.unit)}</h3><p>${x.reason?e(x.reason):'Original fictional fixture; no real astronaut measurement.'}</p><div class="meta">${e(x.time)} · ${e(x.provenance)} · ${x.supersedes?'Supersedes '+e(x.supersedes):'Original revision'}</div></div>`).join('')||'<p>No current assessment has been imported.</p>'}<h3>Comparison source</h3><p>NASA V1 4003 supplies an in-mission relative aerobic-capacity reference of at least 80% of pre-mission capacity. EVA criteria and clinical clearance are separate.</p><a class="text-btn" href="${SOURCE_URL()}" target="_blank" rel="noopener noreferrer">Open NASA source ${icon('external')}</a>`);
}
function showHandover(){
 const ep=D.episodeFor(state,sid());if(!ep||!readAllowed())return notify('An accessible review request is required.',true);
 const next=state.operations.reviewers.find(r=>r.id!==(ep.owner??ep.handover?.to)&&r.available)?.id??ep.handover?.to;
 showModal('Offer review responsibility',`<p>The recipient must explicitly accept. ${ep.owner?e(ep.owner)+' remains responsible until then.':'The crew member remains responsible for finding an available reviewer.'}</p><form id="assignment-form"><div class="field"><label for="assignment-reviewer">Proposed reviewer</label><select id="assignment-reviewer" name="reviewer">${state.operations.reviewers.map(r=>`<option value="${e(r.id)}" ${r.id===next?'selected':''}>${e(r.label)} · ${e(r.assignment)} · ${r.available?'Available':'Occupied'}</option>`).join('')}</select></div><div class="field"><label for="assignment-reason">Handover reason</label><textarea id="assignment-reason" name="reason" required maxlength="500">Primary reviewer is occupied with another mission task. Request available backup review of this assessment context.</textarea></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">Offer responsibility →</button></div></form>`);
}
function showReview(){
 if(!D.ownsReview(state,actor(),sid()))return notify('Accept this assignment as an available reviewer first.',true);
 const dep=D.dependency(state,sid());showModal('Record onboard review',`<p>Record an assessment-context disposition and a named follow-up. This demonstration does not generate treatment advice.</p><form id="review-form" data-dependency="${e(dep)}"><div class="field"><label for="review-disposition">Disposition</label><input id="review-disposition" value="Assessment context requires clarification" readonly></div><div class="field"><label for="review-note">Context to review</label><textarea id="review-note" name="note" required maxlength="1000">Verify the assessment method, selected baseline and unspecified measurement uncertainty.</textarea></div><div class="field"><label for="follow-owner">Follow-up owner</label><input id="follow-owner" value="${e(actor().id)} · Accepted onboard reviewer" readonly></div><div class="field"><label for="follow-trigger">Follow-up due event</label><input id="follow-trigger" name="trigger" required maxlength="300" value="When assessment method and baseline context have been checked"><small>A named event keeps responsibility visible without inventing a clinical deadline.</small></div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save review and follow-up ${icon('check')}</button></div></form>`);
}
function prepareHandoff(){
 if(!D.ownsReview(state,actor(),sid()))return notify('Use the assigned onboard reviewer role.',true);
 if(!D.currentReview(state,sid()))return notify('Record a review of the current evidence first.',true);
 showModal('Prepare a ground handoff',`<p>Required evidence stays in the packet: both values and units, methods, original times, revision IDs, baseline selection, uncertainty and the comparison source.</p>${metaRows([['Recipient','SIM-GROUND-01'],['Purpose','Review assessment context and comparison applicability'],['Source mode','Entirely fictional demonstration']])}<form id="handoff-form" style="margin-top:20px"><div class="field"><label for="ground-question">Question for the ground reviewer</label><textarea id="ground-question" name="question" maxlength="500">Please review the assessment context and the applicability of the selected baseline comparison.</textarea></div><label class="checkline"><input type="checkbox" name="includeNote" checked>Include the onboard reviewer’s context note</label><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Create exact preview ${icon('arrow')}</button></div></form>`);
}
function packetDetails(p,preview=false){
 const a=p.payload;return `<div class="notice ${p.historical?'':'neutral'}">${preview?'This is a frozen preview. Approval releases these exact bytes into the local simulation queue.':p.historical?'Historical evidence snapshot. Newer onboard data does not change these approved bytes.':'Immutable received or released snapshot. Browser events are simulated.'}</div>${metaRows([['Packet',a.packetId],['Recipient',a.recipient],['Purpose',a.purpose],['Subject',a.subjectId],['Current assessment',a.assessment.current.value+' '+a.assessment.current.unit],['Selected baseline',a.assessment.baseline.value+' '+a.assessment.baseline.unit],['Relative comparison',a.comparison.percentOfBaseline+'% of baseline'],['Current / baseline times',a.assessment.current.time+' / '+a.assessment.baseline.time],['Method',a.assessment.current.method],['Measurement uncertainty',a.comparison.uncertainty],['Clinical applicability',a.comparison.clinicalApplicability]])}${a.workflowContext?`<h3>Responsibility at release</h3>${metaRows([['Task',a.workflowContext.task.id],['Accepted owner',a.workflowContext.owner],['Accepted assignment',a.workflowContext.acceptedAssignment.assignmentId]])}`:''}<h3>Question for ground</h3><p>${e(a.question||'No additional question.')}</p>${a.onboardNote?`<h3>Onboard context note</h3><p>${e(a.onboardNote)}</p>`:''}<h3>Exact evidence revisions</h3><div class="hash">${e(a.assessment.current.id)}<br>${e(a.assessment.baseline.id)}</div><h3>SHA-256 of the exact payload</h3><div class="hash">${e(p.hash)}</div><div class="card-actions">${textBtn('Inspect serialized payload',preview?'draft-json':'packet-json',`data-id="${e(p.id)}"`)}</div>`;
}
function showDraft(did){const d=state.drafts.find(d=>d.id===did);if(!d||role!=='onboard'||!D.canRead(state,actor(),d.subjectId))return notify('This preview is unavailable to the current role.',true);const stale=d.stale||d.dependency!==D.dependency(state,d.subjectId);showModal('Approve the exact handoff',packetDetails(d,true)+(stale?'<div class="notice error">This preview is stale. Re-review current evidence and prepare a new packet.</div>':'')+`<div class="form-actions">${btn('Change details','prepare-handoff')}${btn(d.released?'Already released':'Approve and queue','approve','primary',`data-id="${e(d.id)}" data-hash="${e(d.hash)}" ${stale||d.released?'disabled':''}`)}</div>`);}
function canSeePacket(p){return p&&(role==='ground'?D.groundPackets(state,actor()).some(x=>x.id===p.id):D.canRead(state,actor(),p.subjectId));}
function showPacket(pid){const p=state.packets.find(p=>p.id===pid);if(!canSeePacket(p))return notify('This role has no access to the packet.',true);showModal('Released evidence snapshot',packetDetails(role==='ground'?{...p,historical:false}:p)+`<div class="form-actions">${btn('Download exact payload','download-packet','',`data-id="${e(p.id)}"`)}</div>`);}
function showGroundReview(pid){const p=D.groundPackets(state,actor()).find(p=>p.id===pid);if(!p)return notify('This role has no received packet to review.',true);showModal('Record ground context review',`<p>This records a simulated review of ${e(p.id)} and its exact hash. It does not resolve the separate onboard follow-up.</p><div class="hash">SHA-256 · ${e(p.hash)}</div><form id="ground-form" data-id="${e(p.id)}" style="margin-top:20px"><div class="field"><label for="ground-note">Review note</label><textarea id="ground-note" name="note" required maxlength="1000">Assessment context reviewed in this simulation. Onboard follow-up remains assigned to verify method and uncertainty.</textarea></div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Record ground review ${icon('check')}</button></div></form>`);}
function showCorrection(){if(!D.ownsReview(state,actor(),sid()))return notify('Use the assigned onboard reviewer role.',true);const [,cur]=D.activeRecords(state,sid());if(!cur)return notify('No current assessment is available.',true);showModal('Append an assessment correction',`<p>The prior revision remains in history. This creates new evidence, invalidates current review readiness and unreleased previews, and preserves released packets unchanged.</p><form id="correction-form" data-current="${e(cur.id)}"><div class="form-grid"><div class="field"><label for="corrected-value">Corrected fictional value</label><input id="corrected-value" name="value" inputmode="decimal" value="${e(cur.value)}" required></div><div class="field"><label for="corrected-unit">Raw unit</label><select id="corrected-unit" name="unit"><option ${cur.unit==='mL/min/kg'?'selected':''}>mL/min/kg</option><option ${cur.unit==='L/min'?'selected':''}>L/min</option></select></div></div><div class="field"><label for="correction-reason">Correction reason</label><textarea id="correction-reason" name="reason" required maxlength="500" placeholder="Explain the change to this fictional assessment."></textarea></div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Append revision ${icon('check')}</button></div></form>`);}
function showFollowUp(fid){const f=D.episodeFor(state,sid())?.followUps.find(f=>f.id===fid);if(!f||role!=='onboard'||!readAllowed())return notify('This follow-up is unavailable to the current role.',true);showModal('Record follow-up outcome',`${metaRows([['Owner',f.owner],['Due event',f.trigger]])}<form id="follow-form" data-id="${e(fid)}" style="margin-top:20px"><div class="field"><label for="follow-outcome">Observed outcome in this simulation</label><textarea id="follow-outcome" name="outcome" required maxlength="1000" placeholder="Record what the assigned reviewer actually checked."></textarea><small>Recording an outcome closes this task. It does not declare the crew member healthy.</small></div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save outcome ${icon('check')}</button></div></form>`);}
function showReset(intake=false){showModal(intake?'Start a fresh walkthrough':'Reset fictional mock data',`<p>${intake?'Start with a selected preflight baseline, then import Crew 03’s fictional assessment and follow the complete review-to-handoff path.':'Restore the original six fictional crew fixtures.'} This replaces only this mock’s stored reviews, corrections and packets in this browser.</p><div class="form-actions"><button class="btn" data-action="close-modal">Cancel</button>${btn(intake?'Start fresh scenario':'Reset mock','confirm-reset','primary',`data-intake="${intake?'yes':'no'}"`)}</div>`);}
function doReset(intake){try{const next=D.createState({intake});localStorage.setItem(KEY,JSON.stringify(next));state=next;lastSaved=new Date().toISOString();storageProblem='';guide=intake;role='crew';subjectId='SIM-C03';view='review';closeModal();render();notify(intake?'Fresh fictional scenario ready. Import the assessment to begin.':'Fictional mock restored.');}catch(err){notify('The reset could not be saved. '+err.message,true);}}
function switchRole(next){closeModal();role=next;subjectId='SIM-C03';view=next==='ground'?'ground':next==='technical'?'system':'today';render();document.querySelector('#main')?.focus({preventScroll:true});}
function navigate(next){closeModal();view=next;render();document.querySelector('#main')?.focus({preventScroll:true});}
function download(p){if(!canSeePacket(p))return notify('Packet access unavailable.',true);const blob=new Blob([p.bytes],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=p.id+'-fictional-payload.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

document.addEventListener('click',event=>{
 const b=event.target.closest('[data-action],[data-view]');if(!b||b.disabled)return;
 if(b.dataset.view){navigate(b.dataset.view);return;}
 const a=b.dataset.action;
 if(a==='close-modal')return closeModal();
 if(a==='load-research'){loadResearch();return;}
 if(a==='load-scenario'){showScenarioReset(b.dataset.id);return;}
 if(a==='confirm-scenario'){startScenario(b.dataset.id);return;}
 if(a==='toggle-replay'){const r=transact(s=>{if(!s.simulation)throw Error('Load a scenario first.');s.simulation.running=!s.simulation.running;},{control:true});if(r.ok)render();return;}
 if(a==='step-replay'){const r=transact(s=>{if(!s.simulation||s.simulation.running)throw Error('Pause a loaded scenario first.');s.simulation.running=true;S.advance(s,15);s.simulation.running=false;},{control:true});if(r.ok)render();return;}
 if(a==='lab-toggle-recorder'){const r=transact(s=>{if(!s.simulation)throw Error('Load a scenario first.');s.simulation.recorder=!s.simulation.recorder;s.simulation.events.push({at:s.simulation.elapsed,label:'Operator set fictional recorder '+(s.simulation.recorder?'available.':'unavailable.'),kind:'operator'});},{control:true});if(r.ok)render();return;}
 if(a==='run-checks'){checkResults=S.runChecks();render();notify(checkResults.every(r=>r.status==='passed')?'12 isolated behavior checks passed. Active care data unchanged.':'A behavior check failed. Inspect the run report.',checkResults.some(r=>r.status==='failed'));return;}
 if(a==='export-run'){exportRun();return;}
 if(a==='domain-bone'||a==='domain-behavior'){showDomain(a);return;}
 if(a==='go-brief'&&!['crew','onboard'].includes(role)){switchRole('crew');return;}
 if(a.startsWith('go-'))return navigate(a.slice(3));
 if(a==='start-guide')return showReset(true);if(a==='reset')return showReset(false);if(a==='confirm-reset')return doReset(b.dataset.intake==='yes');if(a==='end-guide'){guide=false;render();return;}
 if(a==='switch-onboard'||a==='guide-onboard')return switchRole('onboard');if(a==='switch-ground'||a==='guide-ground')return switchRole('ground');
 if(a==='guide-crew'){switchRole('crew');return;}
 if(a==='guide-handoff'){switchRole('onboard');navigate('transfer');prepareHandoff();return;}
 if(a==='guide-transfer'){switchRole('onboard');navigate('transfer');return;}
 if(a==='evidence-detail')return showEvidence();if(a==='record-review')return showReview();if(a==='prepare-handoff')return prepareHandoff();if(a==='open-draft')return showDraft(b.dataset.id);if(a==='packet-detail')return showPacket(b.dataset.id);if(a==='ground-review')return showGroundReview(b.dataset.id);if(a==='correct')return showCorrection();if(a==='follow-up')return showFollowUp(b.dataset.id);
 if(a==='switch-crew')return switchRole('crew');
 if(a==='switch-reviewer'){reviewerId=b.dataset.id;switchRole('onboard');return;}
 if(a==='offer-handover')return showHandover();
 if(a==='accept-review'){const r=transact(s=>D.acceptReview(s,actor(),sid(),b.dataset.id,D.dependency(s,sid())));if(r.ok){render();notify('Responsibility accepted. Pending follow-up belongs to '+actor().id+'.');}return;}
 if(a==='reviewer-duty'){const r=transact(s=>D.setReviewerAvailability(s,actor(),b.dataset.id,!D.reviewerFor(s,b.dataset.id).available));if(r.ok)render();return;}
 if(a==='request-review'){const r=transact(s=>D.requestReview(s,actor(),sid()));if(r.ok){render();notify('Review requested. The offered reviewer must accept responsibility.');}return;}
 if(a==='replay'){const r=transact(s=>D.importFixture(s,actor(),sid()));if(r.ok){render();notify(r.result.accepted?'Fictional assessment imported. Original method and time preserved.':'Identical fixture recognized. No assessment was duplicated.');}return;}
 if(a==='approve'){const r=transact(s=>D.approvePacket(s,actor(),b.dataset.id,b.dataset.hash));if(r.ok){closeModal();view='transfer';render();notify('Exact packet approved and queued in this browser.');}return;}
 if(a==='deliver'){const r=transact(s=>D.deliverPacket(s,actor(),b.dataset.id));if(r.ok){render();notify('Simulated receipt recorded. Ground review is still a separate step.');}return;}
 if(a==='connect-earth'){const r=transact(s=>s.faults.earth=true,{control:true});if(r.ok){render();notify('Simulated Earth link connected. No external connection was opened.');}return;}
 if(a==='toggle-fault'){const k=b.dataset.key;if(!['earth','lan','node','grant'].includes(k))return;const r=transact(s=>{s.faults[k]=!s.faults[k];if(s.simulation)s.simulation.events.push({at:s.simulation.elapsed,label:'Operator set '+k+' '+(s.faults[k]?'available.':'unavailable.'),kind:'operator'});},{control:true});if(r.ok)render();return;}
 if(a==='packet-json'||a==='draft-json'){
  const p=a==='packet-json'?state.packets.find(x=>x.id===b.dataset.id):state.drafts.find(x=>x.id===b.dataset.id);
  const allowed=a==='packet-json'?canSeePacket(p):role==='onboard'&&p&&D.canRead(state,actor(),p.subjectId);
  if(!allowed)return notify('Evidence access unavailable.',true);showModal('Exact serialized payload',`<p>The hash applies to this exact canonical UTF-8 string.</p><pre class="code-view">${e(p.bytes)}</pre><div class="hash">SHA-256 · ${e(p.hash)}</div>`);return;
 }
 if(a==='download-packet')return download(state.packets.find(p=>p.id===b.dataset.id));
 if(a==='about')showModal('About this mock MVP',`<div class="reading"><h3>What works here</h3><p>Fictional assessment intake, exact decimal comparison, evidence inspection, accountable review and follow-up, immutable handoff previews and hashes, simulated delivery, separate ground review, corrections and restoration from browser storage.</p><h3>What the prototype represents</h3><p>The design uses NASA’s health and interface references. Crew profiles, role grants and measurements are fictional. The explanation uses a deterministic template. A separate research workspace verifies the retained OSD-569 blood-count files. A virtual-clock adapter replays fictional assessments, and the scenario lab runs isolated domain checks. The application has no live NASA API, physical device, clinical backend or connected language model. Two fictional CMO assignments illustrate role overlap; operational training and authority remain unvalidated.</p><h3>Preparation status</h3><p>This is an independent design mock. Event eligibility and the full 2026 challenge requirements still require review. No NASA endorsement, clinical validation or operational readiness is claimed.</p></div>`);
});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.change==='scenario'){selectedScenario=el.value;render();return;}if(el.dataset.change==='research-subject'){researchSubject=el.value;render();return;}if(el.dataset.change==='research-analyte'){researchAnalyte=el.value;render();return;}if(el.dataset.change==='reviewer'){reviewerId=el.value;closeModal();view='today';render();return;}if(el.dataset.change==='role')switchRole(el.value);if(el.dataset.change==='subject'){closeModal();subjectId=el.value;view='brief';render();}});
document.addEventListener('submit',event=>{
 const f=event.target;if(!f.id.endsWith('-form'))return;event.preventDefault();if(!f.reportValidity())return;
 const data=new FormData(f);let r;
 if(f.id==='assignment-form')r=transact(s=>D.offerHandover(s,actor(),sid(),data.get('reviewer'),data.get('reason')));
 if(f.id==='review-form')r=transact(s=>D.recordReview(s,actor(),sid(),{note:data.get('note'),trigger:data.get('trigger'),expectedDependency:f.dataset.dependency}));
 if(f.id==='handoff-form'){
  r=transact(s=>D.previewPacket(s,actor(),sid(),{question:data.get('question'),includeNote:data.has('includeNote')}));
  if(r.ok){render();showDraft(r.result.id);}return;
 }
 if(f.id==='correction-form')r=transact(s=>D.correctAssessment(s,actor(),sid(),{value:data.get('value'),unit:data.get('unit'),reason:data.get('reason'),expectedCurrentId:f.dataset.current}));
 if(f.id==='ground-form')r=transact(s=>D.recordGroundReview(s,actor(),f.dataset.id,data.get('note')));
 if(f.id==='follow-form')r=transact(s=>D.resolveFollowUp(s,actor(),sid(),f.dataset.id,data.get('outcome')));
 if(r?.ok){closeModal();if(f.id==='review-form'||f.id==='follow-form')view='care';render();notify(f.id==='correction-form'?'New revision saved. Review readiness and unreleased previews invalidated.':f.id==='ground-form'?'Ground review recorded. Onboard follow-up retains its own state.':'Review responsibility saved in this browser.');}
});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
window.addEventListener('storage',event=>{if(event.key!==KEY)return;try{const s=readStored();if(s){state=s;closeModal();render();notify('Simulation updated from another tab. Open work was refreshed.');}}catch(err){notify('Stored simulation could not be refreshed.',true);}});

async function loadResearch(){
 if(researchLoading)return;researchLoading=true;researchError='';render();
 try{researchReport=await R.loadCBC();}catch(err){researchReport=null;researchError=err.message;notify(err.message,true);}finally{researchLoading=false;render();}
}
function showScenarioReset(id){
 const spec=S.SCENARIOS.find(s=>s.id===id);if(!spec)return;
 showModal('Load a repeatable scenario',`<p><strong>${e(spec.title)}</strong></p><p>${e(spec.description)}</p><p>This resets the fictional crew workflow in this browser, including its reviews and packets. Research files stay unchanged. Automatic replay only delivers fictional input and approved packets; care decisions still need an explicit user action.</p><div class="form-actions">${btn('Cancel','close-modal')}${btn('Load scenario','confirm-scenario','primary',`data-id="${e(id)}"`)}</div>`);
}
function startScenario(id){
 try{const next=S.createScenario(id);next.version=state.version+1;localStorage.setItem(KEY,JSON.stringify(next));state=next;selectedScenario=id;lastSaved=new Date().toISOString();storageProblem='';guide=false;role='crew';subjectId='SIM-C03';reviewerId='SIM-A02';view='today';closeModal();render();notify('Scenario loaded. Run replay or advance the virtual clock.');}catch(err){notify('Scenario could not be saved. '+err.message,true);}
}
function exportRun(){
 if(!checkResults.length)return;
 const data={schema:'chnai-scenario-report/1',createdAt:new Date().toISOString(),scope:'Browser-local software checks; not clinical or hardware validation',checks:checkResults,activeScenario:state.simulation?{id:state.simulation.id,elapsed:state.simulation.elapsed,events:state.simulation.events}:null,limitations:['Clinical actions unreviewed','No physical device or real ground link','Not all planned scenarios implemented']};
 const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='CHNAI-scenario-run.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function showDomain(action){
 const bone=action==='domain-bone';showModal(bone?'Bone and muscle monitoring':'Behavior and sleep monitoring',`<p>${bone?'There is no qualified crew DXA or strength assessment in this prototype. Exercise logs would describe a countermeasure, not directly measure bone density.':'There is no qualified crew sleep, cognition or private self-report input in this prototype. Missing input does not establish normal mood or sleep.'}</p><p>NASA Standard Measures identifies relevant research measurement domains. Adding a crew workflow requires a suitable input, method context, scoped access and reviewed interpretation.</p><a class="text-btn" href="https://www.nasa.gov/reference/standard-measures/" target="_blank" rel="noopener noreferrer">Read NASA Standard Measures ↗</a>`);
}
setInterval(()=>{
 if(!state.simulation?.running||modal.open||document.hidden)return;
 const r=transact(s=>S.advance(s,15),{control:true});
 if(!r.ok){state.simulation.running=false;return;}
 // Avoid replacing an active selection while a virtual clock is ticking.
 if(document.activeElement?.matches('select,input,textarea'))return;
 if(r.result||view==='lab'||view==='brief'||view==='today')render();else document.querySelectorAll('[data-replay-clock]').forEach(el=>el.textContent=' +'+S.clockLabel(state.simulation.elapsed));
},1000);

render();
